import { escapeHtml, time } from '../shared/formatters.js';
import { sourceBadge } from '../shared/ui.js';

const paths = {
    overview: '<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
    building: '<path d="M5 21V7l7-4 7 4v14M3 21h18M9 9h1m4 0h1m-6 4h1m4 0h1m-5 8v-4h4v4"/>',
    hierarchy: '<rect x="9" y="3" width="6" height="5" rx="1"/><rect x="2" y="16" width="6" height="5" rx="1"/><rect x="16" y="16" width="6" height="5" rx="1"/><path d="M12 8v4M5 16v-4h14v4"/>',
    document: '<path d="M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h7"/>',
};
export const icon = (name) => `<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">${paths[name] || paths.document}</svg>`;

export function shell(module, snapshot, state, pageHtml, options = {}) {
    const page = module.pages.find((entry) => entry.id === state.page);
    const project = snapshot?.projects.find((entry) => entry.id === state.projectId);
    return `<a class="tp-skip-link" href="#main-content">Đến nội dung chính</a><aside id="sidebar" class="tp-sidebar" aria-label="Điều hướng phòng ban"><div class="tp-brand"><span class="tp-brand-mark" aria-hidden="true"><svg viewBox="0 0 34 34" width="28" height="28" fill="none"><path d="M5 26V8h24M17 8v18M10 26h14" stroke="currentColor" stroke-width="3"/><path d="M24 13h5v7h-5z" fill="currentColor"/></svg></span><div><span class="tp-brand-title">Tấn Phát</span><span class="tp-brand-subtitle">Quản trị doanh nghiệp</span></div></div><div class="tp-department"><span class="tp-department-label">Phòng ban</span><strong>${escapeHtml(module.name)}</strong><span class="tp-department-tag">Không gian làm việc</span></div><p class="tp-nav-label">Quản lý dự án</p><nav class="tp-nav" aria-label="Trang dashboard">${module.pages.map((entry) => `<button class="tp-nav-button" data-action="navigate" data-page="${entry.id}"${state.page === entry.id ? ' aria-current="page"' : ''}><span class="tp-nav-icon">${icon(entry.icon)}</span>${escapeHtml(entry.name)}</button>`).join('')}</nav><div class="tp-sidebar-foot"><div class="tp-workspace-mark">TP</div><div><strong>Kế hoạch Kinh doanh</strong><span>Giao diện thử nghiệm · v0.1</span></div></div></aside><div class="tp-sidebar-backdrop" data-action="close-menu"></div><div class="tp-main"><header class="tp-topbar"><div class="tp-topbar-context"><p class="tp-kicker">Quản trị Tấn Phát</p><h1 class="tp-page-title" id="page-title" tabindex="-1">${escapeHtml(page.name)}</h1></div><div class="tp-topbar-actions"><span class="tp-module-label">${escapeHtml(module.name)}</span><span class="tp-user-mark" aria-label="Không gian bản mẫu">KH</span></div><button class="tp-mobile-nav" data-action="menu" aria-controls="sidebar" aria-expanded="false" aria-label="Mở điều hướng">☰</button></header><main id="main-content" class="tp-content" tabindex="-1"><div class="tp-meta-row"><div class="tp-breadcrumb">Dự án <span aria-hidden="true">/</span> <strong>${escapeHtml(project?.code || 'Đang tải')}</strong></div>${sourceBadge()}</div>${snapshot ? `<div class="tp-project-toolbar"><div class="tp-field tp-project-field"><label for="project-select">Dự án đang xem</label><select class="tp-select" id="project-select" data-field="projectId">${snapshot.projects.map((entry) => `<option value="${escapeHtml(entry.id)}"${entry.id === state.projectId ? ' selected' : ''}>${escapeHtml(entry.code)} — ${escapeHtml(entry.name)}</option>`).join('')}</select></div><div class="tp-snapshot-actions"><span class="tp-snapshot-time">Nạp mẫu lúc ${time(snapshot.loadedAt)}</span><button class="tp-button" data-action="refresh"${options.loading ? ' disabled' : ''}>${options.loading ? 'Đang nạp…' : 'Làm mới mẫu'}</button></div></div>` : ''}<div id="page-content" aria-busy="${Boolean(options.loading)}">${pageHtml}</div><footer class="tp-content-foot">Dữ liệu hoàn toàn giả lập để duyệt giao diện. Chưa kết nối Odoo hoặc sổ dự án thực tế.</footer></main></div><dialog class="tp-dialog" id="formula-dialog" aria-labelledby="formula-title"><div class="tp-panel-heading"><h2 id="formula-title">Cách đọc số liệu</h2><button class="tp-button" data-action="close-dialog">Đóng</button></div><dl class="tp-reading-notes"><div><dt>Hợp đồng cập nhật</dt><dd>Phụ lục dương cuối cùng theo thứ tự nguồn thay thế toàn bộ giá trị hợp đồng; không có phụ lục thì dùng tổng hợp đồng gốc.</dd></div><div><dt>Còn theo nghiệm thu</dt><dd>Nghiệm thu − tiền đã thanh toán. Giữ số âm để nhận biết tạm ứng hoặc nghiệm thu chưa cập nhật.</dd></div><div><dt>Khoán cấp 1 và cấp 2</dt><dd>Tổng công ty chỉ tính cấp 1. Cấp 2 thuộc khoán của phòng và được theo dõi riêng.</dd></div><div><dt>Tỷ lệ thanh toán</dt><dd>Tổng tiền / tổng nghiệm thu cùng phạm vi. Mẫu bằng 0 thì chưa xác định; tỷ lệ có thể vượt 100%.</dd></div><div><dt>Phạm vi bộ lọc</dt><dd>Lọc hạng mục, đơn vị, cấp đổi số tài chính trong trang. Tìm kiếm và sắp xếp bảng chỉ đổi dòng hiển thị. Lọc ngày chỉ áp dụng trong tab giao dịch.</dd></div></dl></dialog>`;
}
